from pathlib import Path
p=Path('/home/ubuntu/nox-offline-player/client/src/pages/Home.tsx')
s=p.read_text()
s=s.replace('type Cue = { start: number; end: number; text: string };', 'type Cue = { start: number; end: number; text: string; translation?: string };')
s=s.replace('  const [transcribing, setTranscribing] = useState(false);', '  const [transcribing, setTranscribing] = useState(false);\n  const [translating, setTranslating] = useState(false);\n  const [translationEnabled, setTranslationEnabled] = useState(false);')
# overlay bilingual
s=s.replace('{activeCue && <div className="pointer-events-none absolute bottom-7 left-1/2 max-w-[85%] -translate-x-1/2 rounded-lg bg-black/75 px-5 py-3 text-center font-display text-lg shadow-lg backdrop-blur-md" style={{ fontSize: `${captionSize}rem`, transform: `translateX(-50%) translateY(${-captionOffset}px)` }}>{activeCue.text}</div>}', '{activeCue && <div className="pointer-events-none absolute bottom-7 left-1/2 max-w-[88%] -translate-x-1/2 rounded-xl bg-black/80 px-5 py-3 text-center shadow-lg backdrop-blur-md" style={{ transform: `translateX(-50%) translateY(${-captionOffset}px)` }}><div className="font-display text-lg" style={{ fontSize: `${captionSize}rem` }}>{activeCue.text}</div>{translationEnabled && activeCue.translation && <div className="mt-1 border-t border-white/15 pt-1 text-sm text-[#dfffaa]">{activeCue.translation}</div>}</div>}')
# button add after transcribe
needle='<button onClick={() => void transcribeCurrent()} disabled={!current || transcribing} className="secondary-button disabled:cursor-wait disabled:opacity-50"><Mic2 size={15} /> {transcribing ? "Whisper 轉錄中…" : "Whisper 自動轉錄"}</button>'
replacement=needle+'<button onClick={() => void listenTranslateCurrent()} disabled={!current || transcribing || translating} className="secondary-button disabled:cursor-wait disabled:opacity-50"><Languages size={15} /> {translating ? "聽譯處理中…" : "一鍵聽譯（英→中）"}</button>'
if needle not in s: raise SystemExit('button needle missing')
s=s.replace(needle,replacement)
# insert function before useEffect cleanup
needle='''  useEffect(() => () => transcriptionWorkerRef.current?.terminate(), []);'''
func='''  async function listenTranslateCurrent() {\n    if (!current || transcribing || translating) return;\n    setTranscribing(true);\n    setTranslating(true);\n    setTranslationEnabled(false);\n    setNotice("正在聽取語音並翻譯；首次使用會下載 Whisper 與 Opus-MT 模型並快取");\n    const worker = new Worker(new URL("../lib/whisper.worker.ts", import.meta.url), { type: "module" });\n    transcriptionWorkerRef.current?.terminate();\n    transcriptionWorkerRef.current = worker;\n    let translated: Cue[] = [];\n    let translateIndex = 0;\n    let sourceCues: Cue[] = [];\n    const finish = () => { worker.terminate(); setTranscribing(false); setTranslating(false); transcriptionWorkerRef.current = null; };\n    worker.onmessage = (event: MessageEvent<{ type: string; result?: unknown; message?: string }>) => {\n      const data = event.data;\n      if (data.type === "transcription") {\n        const result = data.result as { text?: string; chunks?: Array<{ timestamp?: [number, number]; text?: string }> } | undefined;\n        sourceCues = (result?.chunks ?? []).map((chunk) => ({ start: chunk.timestamp?.[0] ?? 0, end: chunk.timestamp?.[1] ?? 0, text: chunk.text?.trim() ?? "" })).filter((cue) => cue.text && cue.end > cue.start);\n        if (!sourceCues.length && result?.text?.trim()) sourceCues = [{ start: 0, end: duration || 3600, text: result.text.trim() }];\n        if (!sourceCues.length) { setNotice("聽譯未取得可辨識的語音"); finish(); return; }\n        translated = sourceCues.map((cue) => ({ ...cue }));\n        translateIndex = 0;\n        worker.postMessage({ type: "translate", model: "Xenova/opus-mt-en-zh", text: sourceCues[0].text });\n        return;\n      }\n      if (data.type === "translation") {\n        const result = data.result as Array<{ translation?: string }> | { translation?: string } | undefined;\n        const first = Array.isArray(result) ? result[0] : result;\n        translated[translateIndex].translation = first?.translation?.trim() ?? "";\n        translateIndex += 1;\n        if (translateIndex < translated.length) {\n          setNotice(`聽譯中… ${translateIndex + 1} / ${translated.length} 段`);\n          worker.postMessage({ type: "translate", model: "Xenova/opus-mt-en-zh", text: sourceCues[translateIndex].text });\n        } else {\n          setCues(translated);\n          setTranslationEnabled(true);\n          setPanel("captions");\n          setNotice(`聽譯完成：已產生 ${translated.length} 段中英雙語字幕`);\n          finish();\n        }\n        return;\n      }\n      if (data.type === "error") { setNotice("聽譯失敗：" + (data.message ?? "請先在模型庫下載 Whisper 與 Opus-MT 英中模型")); finish(); }\n    };\n    worker.onerror = () => { setNotice("聽譯工作執行緒無法啟動"); finish(); };\n    try {\n      const context = new AudioContext();\n      const buffer = await context.decodeAudioData(await fetch(current.url).then((response) => response.arrayBuffer()));\n      const length = Math.ceil(buffer.duration * 16000);\n      const audio = new Float32Array(length);\n      for (let channel = 0; channel < buffer.numberOfChannels; channel++) {\n        const source = buffer.getChannelData(channel);\n        for (let index = 0; index < length; index++) audio[index] += (source[Math.min(source.length - 1, Math.floor(index * source.length / length))] ?? 0) / buffer.numberOfChannels;\n      }\n      await context.close();\n      worker.postMessage({ type: "transcribe", model: "Xenova/whisper-tiny", audio }, [audio.buffer]);\n    } catch (error) { setNotice("聽譯音訊讀取失敗：" + (error instanceof Error ? error.message : "請確認檔案格式")); finish(); }\n  }\n\n'''+needle
if needle not in s: raise SystemExit('cleanup needle missing')
s=s.replace(needle,func)
# caption panel shows translation text and toggle
s=s.replace('<p className="mt-3 text-sm leading-6 text-white/80">{activeCue.text}</p>', '<p className="mt-3 text-sm leading-6 text-white/80">{activeCue.text}</p>{activeCue.translation && <p className="mt-2 border-t border-white/10 pt-2 text-sm leading-6 text-[#dfffaa]">{activeCue.translation}</p>}')
s=s.replace('<span className={cn("text-white/45", activeCue?.text === cue.text && "text-[#c9ff65]")}>{cue.text}</span>', '<span className={cn("text-white/45", activeCue?.text === cue.text && "text-[#c9ff65]")}>{cue.text}{cue.translation && <span className="mt-1 block text-[#dfffaa]/70">{cue.translation}</span>}</span>')
# Model library explanatory panel stronger
s=s.replace('Whisper 產生字幕後，可使用已快取的 Opus-MT 模型進行本機翻譯；模型與音訊都不會送到雲端。', '按播放器的「一鍵聽譯（英→中）」即可先用 Whisper tiny 辨識，再用 Opus-MT 英文 → 中文逐段翻譯，最後載入雙語字幕軌。模型與音訊都不會送到雲端。')
p.write_text(s)
